import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { publicAPI, eventAPI } from '../../services/api';
import { useAuth } from '../../context/AuthContext';
import { useToast } from '../../components/Toast';
import Loader from '../../components/Loader';
import EmptyState from '../../components/EmptyState';
import Button from '../../components/Button';
import Card from '../../components/Card';

const EventsPage = () => {
  const { isAuthenticated } = useAuth();
  const toast               = useToast();
  const [events,  setEvents]  = useState([]);
  const [loading, setLoading] = useState(true);
  const [joining, setJoining] = useState(null);
  const [error,   setError]   = useState('');

  useEffect(() => {
    publicAPI.getEvents()
      .then(res => setEvents(res.data))
      .catch(() => setError('Failed to load events.'))
      .finally(() => setLoading(false));
  }, []);

  const handleJoin = async (eventId) => {
    setJoining(eventId);
    try {
      const res = await eventAPI.joinEvent(eventId);
      setEvents(prev => prev.map(e => e.id === eventId ? res.data : e));
      toast.success('You have joined this event!', { title: 'Registered ✅' });
    } catch (err) {
      toast.error(err.response?.data?.error || 'Failed to join event.', { title: 'Could not join' });
    } finally {
      setJoining(null);
    }
  };

  return (
    <div style={{ background: 'var(--eco-bg)', minHeight: '100vh' }}>
      <div className="section-header">
        <h1 className="section-header__title">📅 Events</h1>
        <p className="section-header__subtitle">Sustainability events near you. Join to make a collective impact.</p>
      </div>

      <div className="container" style={{ padding: 'var(--space-10) var(--space-6)' }}>
        {!isAuthenticated && (
          <div className="alert alert-info mb-6">
            🔒 <Link to="/login" style={{ fontWeight: 600 }}>Sign in</Link> to join events and track your participation.
          </div>
        )}

        {error && <div className="alert alert-error">{error}</div>}

        {loading ? (
          <Loader text="Loading events..." />
        ) : events.length === 0 ? (
          <EmptyState icon="📅" title="No events scheduled" subtitle="Check back soon for upcoming sustainability events!" />
        ) : (
          <div className="grid grid--auto">
            {events.map(event => {
              const pct = (event.currentParticipants / event.maxParticipants) * 100;
              return (
                <Card key={event.id}>
                  <Card.Body>
                    {/* Status badges */}
                    <div className="flex gap-2 mb-4" style={{ flexWrap: 'wrap' }}>
                      <span className={`badge ${event.full ? 'badge--error' : 'badge--success'}`}>
                        {event.full ? '🔴 Full' : `🟢 ${event.maxParticipants - event.currentParticipants} spots left`}
                      </span>
                      {event.joined && <span className="badge badge--info">✓ Joined</span>}
                    </div>

                    <h3 style={{ fontFamily: 'var(--font-display)', fontSize: 'var(--text-md)', fontWeight: 700, marginBottom: 'var(--space-2)', lineHeight: 1.3 }}>
                      {event.title}
                    </h3>
                    <p style={{ fontSize: 'var(--text-sm)', color: 'var(--eco-text-secondary)', lineHeight: 1.6, marginBottom: 'var(--space-4)', flex: 1 }}>
                      {event.description}
                    </p>

                    <div className="flex-col gap-1 mb-4" style={{ fontSize: 'var(--text-sm)', color: 'var(--eco-text-muted)' }}>
                      <span>📍 {event.location}</span>
                      <span>📅 {new Date(event.date).toLocaleString('en-IN', { day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' })}</span>
                    </div>

                    {/* Capacity bar */}
                    <div className="mb-4">
                      <div className="flex-between mb-2" style={{ fontSize: 'var(--text-xs)', color: 'var(--eco-text-muted)' }}>
                        <span>Participants</span>
                        <span>{event.currentParticipants} / {event.maxParticipants}</span>
                      </div>
                      <div className="progress">
                        <div className="progress__bar" style={{
                          width: `${pct}%`,
                          background: pct >= 90 ? 'var(--eco-error)' : pct >= 60 ? 'var(--eco-warning)' : 'var(--eco-primary)',
                        }} />
                      </div>
                    </div>

                    {/* Action */}
                    {isAuthenticated ? (
                      event.joined ? (
                        <div className="flex-center" style={{ padding: 'var(--space-2) 0', fontSize: 'var(--text-sm)', fontWeight: 600, color: 'var(--eco-info)' }}>
                          ✅ You're registered!
                        </div>
                      ) : (
                        <Button variant="primary" size="md" full loading={joining === event.id} disabled={event.full}
                          onClick={() => handleJoin(event.id)}>
                          {event.full ? 'Event Full' : 'Join Event'}
                        </Button>
                      )
                    ) : (
                      <Link to="/login" className="btn btn--secondary btn--md btn--full" style={{ textAlign: 'center' }}>
                        Sign in to Join
                      </Link>
                    )}
                  </Card.Body>
                </Card>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

export default EventsPage;
